  && result.revision === 17 && result.layoutCount === 1 && result.styleCount === 1 && result.owners.length >= 1;
console.log(JSON.stringify({passed,resources,configUnchanged,chatgptPids,live:result},null,2));
if (!passed) process.exitCode = 1;

