command:
(() => {
  const runtime = window.__codexAppExtensionV2;
  const layout = document.querySelector('[data-app-shell-main-content-layout]');
  const surface = runtime?.surface();
  const geometry = (node) => {
    const r = node.getBoundingClientRect();
    return {left:r.left, width:r.width, center:(r.left+r.right)/2, height:r.height};
  };
  const owners = Array.from(layout?.querySelectorAll("[style*='--cae-wide-layout-owner-offset-x']") ?? []);
  const homeDeclaration = Array.from(layout?.querySelectorAll("[class*='thread-content-max-width:42rem']") ?? []);
  return {
    revision:runtime?.implementationRevision,
    viewportWidth:innerWidth,
    layoutCount:surface?.layoutRootCount,
    scrollerCount:surface?.threadScrollerCount,
    editorCount:surface?.editorCount,
    observerCount:runtime?.observerCount(),
    styleCount:document.querySelectorAll('#cae-wide-layout-style').length,
    layout:layout ? geometry(layout) : null,
    owners:owners.map(node => ({
      ...geometry(node),
      hasEditor:!!node.querySelector('.ProseMirror[contenteditable]'),
      bodyWidthConsumer:node.classList.contains('max-w-(--thread-body-max-width)'),
      maxWidth:getComputedStyle(node).maxWidth,
      offset:node.style.getPropertyValue('--cae-wide-layout-owner-offset-x')
    })),
    homeDeclarations:homeDeclaration.map(node => ({...geometry(node), offset:node.style.getPropertyValue('--cae-wide-layout-owner-offset-x')}))
  };
})();

